// ─── Formatting Helpers ───────────────────────────────────────────────────────
function fmtDate(d: string) {
  if (!d) return "";
  try {
    return new Date(d).toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" });
  } catch {
    return d;
  }
}

function fmtTime(t: string) {
  if (!t) return "";
  try {
    const [h, m] = t.split(":").map(Number);
    return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${h >= 12 ? "PM" : "AM"}`;
  } catch {
    return t;
  }
}

function fmtMobileDate(d: string) {
  if (!d) return "";
  try {
    const dateObj = new Date(d);
    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return `${months[dateObj.getMonth()]} ${dateObj.getDate()} , ${dateObj.getFullYear()}`;
  } catch {
    return d;
  }
}

// ─── Scroll Reveal Animation Component ────────────────────────────────────────
function useReveal() {
  const ref = useRef<HTMLDivElement>(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) setVis(true);
    }, { threshold: 0.04 });
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return { ref, vis };
}

function Reveal({ children, delay = 0 }: { children: React.ReactNode; delay?: number }) {
  const { ref, vis } = useReveal();
  return (
    <div
      ref={ref}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        opacity: vis ? 1 : 0,
        transform: vis ? "none" : "translateY(18px)",
        transition: `opacity 0.75s ease ${delay}ms, transform 0.75s ease ${delay}ms`,
      }}
    >
      {children}
    </div>
  );
}

// ─── Absolute positioning layout helpers ──────────────────────────────────────
function Abs({ x = 0, y = 0, w, h, z = 0, children }: { x?: number; y?: number; w?: number; h?: number; z?: number; children: React.ReactNode }) {
  return <div style={{ position: "absolute", left: x, top: y, ...(w !== undefined ? { width: w } : {}), ...(h !== undefined ? { height: h } : {}), zIndex: z }}>{children}</div>;
}

function Section({ h, bg, children, style }: { h: number; bg: string; children: React.ReactNode; style?: React.CSSProperties }) {
  return <div style={{ position: "relative", width: "100%", height: h, background: bg, overflow: "hidden", ...style }}>{children}</div>;
}

