          <p style={{ fontFamily: F.sans, fontSize: "11px", color: "rgba(255,255,255,0.5)", margin: 0 }}>
            A product by <a href="https://3pin.co.in" target="_blank" rel="noopener noreferrer" style={{ color: C.peach, textDecoration: "none", fontWeight: 500 }}>3PIN</a>
          </p>
          
          {/* Socials */}
